for id,npc in pairs(npcs) do
    local old=P.NPCSources[id]
    if not old then P.NPCSources[id]=npc else
        for _,key in ipairs({'points','locations','entrances'}) do if #(old[key] or {})==0 then old[key]=npc[key] end end
    end
end
