for id,sources in pairs(updates) do
    local item=P.ItemMeta[id] or {name=names[id],classID=9};P.ItemMeta[id]=item;item.sources=item.sources or {}
    for _,source in ipairs(sources) do
        local found
        for _,old in ipairs(item.sources) do
            if old.kind==source.kind and ((source.npc and old.npc==source.npc) or (source.locationKey and old.locationKey==source.locationKey) or (not source.npc and not source.locationKey and old.name==source.name and old.zone==source.zone)) then found=old;break end
        end
        if found then
            for key,value in pairs(source) do if found[key]==nil then found[key]=value end end
        else item.sources[#item.sources+1]=source end
    end
end
