for _,entries in pairs(P.Catalog) do for _,recipe in ipairs(entries) do
    local data=recipe.spell and refs[recipe.spell]
    if data then
        recipe.acquisitionItems=recipe.acquisitionItems or {};recipe.referenceURLs=recipe.referenceURLs or {}
        for _,ref in ipairs(data.items) do appendUnique(recipe.acquisitionItems,ref,'id') end
        for _,url in ipairs(data.urls) do appendUnique(recipe.referenceURLs,url) end
    end
end end
